import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {writeFileSync} from 'node:fs';
const {chromium}=createRequire('/home/outsider/github/h5/web/package.json')('playwright');
const browser=await chromium.launch({executablePath:'/usr/bin/google-chrome',headless:true});
const results=[];
try {
 for(const port of [5173,4173]) for(const width of [1440,390]) {
  const origin=`http://127.0.0.1:${port}`,context=await browser.newContext({viewport:{width,height:1000},serviceWorkers:'block'}),page=await context.newPage();
  const errors=[],forbidden=[],methods=new Set();let external=0;
  page.on('pageerror',e=>errors.push(e.name));
  await context.route('**/*',route=>{
   const req=route.request(),url=new URL(req.url());if(url.origin===origin)return route.continue();external++;
   if(url.origin==='https://testnet.mirrornode.hedera.com'&&url.pathname.startsWith('/api/v1/')&&req.method()==='GET')return route.continue();
   if(url.href==='https://testnet.hashio.io/api'&&req.method()==='POST'){
    const body=req.postDataJSON(),calls=Array.isArray(body)?body:[body];
    if(calls.every(x=>['eth_chainId','eth_getBlockByNumber','eth_getCode','eth_call'].includes(x.method))){calls.forEach(x=>methods.add(x.method));return route.continue();}
   }
   forbidden.push({origin:url.origin,method:req.method()});return route.abort();
  });
  await page.goto(origin,{waitUntil:'networkidle'});
  assert.equal(await page.getByTestId('active-account').innerText(),'Wallet not connected.');assert.equal(external,0);
  const check=page.getByRole('button',{name:'Check current T04 state',exact:true});await check.focus();
  assert.equal(await check.evaluate(el=>el===document.activeElement&&getComputedStyle(el).outlineStyle!=='none'),true);
  assert.equal(await page.getByRole('button',{name:'Approve T04 transaction in MetaMask'}).isDisabled(),true);
  let liveRead;
  if(port===4173&&width===1440){
   await page.keyboard.press('Enter');
   await page.getByText('Current chain state read. Saved journal statuses must be reverified by Review next T04 action.',{exact:true}).waitFor({timeout:180000});
   const section=page.locator('section[aria-labelledby="hold-heading"]');liveRead={};
   for(const label of ['Current block / seconds','Seller available / held','Buyer available / held','Supply / cap / config','Buyer KYC','Active Seller Hold IDs','Hold remaining'])
    liveRead[label]=await section.locator('dl > div').filter({has:page.getByText(label,{exact:true})}).locator('dd').innerText();
   assert.equal(liveRead['Seller available / held'],'94 / 0');assert.equal(liveRead['Buyer available / held'],'6 / 0');
   assert.equal(liveRead['Supply / cap / config'],'100 / 1000 / 1');assert.equal(liveRead['Active Seller Hold IDs'],'None');
   assert.equal(await page.getByTestId('active-account').innerText(),'Wallet not connected.');
  }
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);assert.deepEqual(errors,[]);assert.deepEqual(forbidden,[]);
  results.push({port,width,passed:true,noWallet:true,initialExternalRequests:0,visibleFocus:true,noOverflow:true,liveRead,readMethods:[...methods],externalRequests:external,forbidden,errors});
  console.log(JSON.stringify(results.at(-1)));await context.close();
 }
 for(const width of [1440,390]) {
  const context=await browser.newContext({viewport:{width,height:1000}}),page=await context.newPage(),external=[],errors=[];
  await context.route('https://**/*',route=>{external.push(new URL(route.request().url()).origin);return route.abort()});page.on('pageerror',e=>errors.push(e.name));
  await page.goto('file:///home/outsider/github/ETHGlobal_Victor/docs/evidence/029-t04-manual.html');
  await page.evaluate(async()=>{for(const img of document.images)img.loading='eager';await Promise.all([...document.images].map(img=>img.decode()))});
  assert.equal(await page.locator('img').count(),8);assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
  await page.locator('a').first().focus();assert.notEqual(await page.locator('a').first().evaluate(el=>getComputedStyle(el).outlineStyle),'none');assert.deepEqual(external,[]);assert.deepEqual(errors,[]);
  results.push({kind:'existing-offline-gallery',width,passed:true,imagesLoaded:8,noOverflow:true,visibleFocus:true,external,errors});await context.close();
 }
}finally{await browser.close()}
writeFileSync('/tmp/holdbook-judge-browser.json',JSON.stringify({recordedAt:new Date().toISOString(),results},null,2)+'\n');

