harnesses.linksAndEvidence:
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
const files=['README.md','PRODUCT.md','docs/DEMO.md'],links=[];
for(const file of files){
 const text=fs.readFileSync(file,'utf8');
 for(const m of text.matchAll(/\[[^\]]*\]\(([^)]+)\)/g)){
  const href=m[1];if(/^[a-z]+:/i.test(href))continue;
  const [rel,fragment]=href.split('#'),target=path.resolve(path.dirname(file),rel||path.basename(file));
  assert.ok(fs.existsSync(target),`${file}: ${href}`);
  if(fragment&&target.endsWith('.md')){
   const headings=[...fs.readFileSync(target,'utf8').matchAll(/^#+ (.+)$/gm)].map(m=>m[1].toLowerCase().replace(/[^\w\s-]/g,'').replace(/ /g,'-'));
   assert.ok(headings.includes(fragment),href);
  }
  links.push({file,href});
 }
}
const a=JSON.parse(fs.readFileSync('docs/evidence/029-t04-manual.json')).acceptance;
assert.equal(a.final.block,'40241114');
assert.deepEqual([a.final.sellerBalance,a.final.buyerBalance,a.final.sellerHeld,a.final.buyerHeld,a.final.supply],['94','6','0','0','100']);
assert.equal(a.final.buyerKyc.status,1);assert.deepEqual(a.final.sellerHoldIds,[]);assert.deepEqual(a.final.buyerHoldIds,[]);
const states=[['90','0','10'],['90','0','10'],['90','6','4'],['94','6','0']];
assert.equal(a.transactions.length,4);a.transactions.forEach((t,i)=>{assert.equal(t.status,'complete');assert.deepEqual([t.after.sellerBalance,t.after.buyerBalance,t.after.sellerHeld],states[i]);assert.equal(t.after.supply,'100');assert.equal(t.after.buyerHeld,'0')});
assert.deepEqual(a.simulations.results.flatMap(r=>r.cases.map(c=>c.revert)),['InvalidKycStatus','IsNotEscrow','InsufficientHoldBalance']);
assert.ok(a.simulations.results.every(r=>r.passed&&r.fullHistoricalStateMatches&&r.noTransactionOrSignature));
assert.ok(a.simulations.results[0].genuineSdkHistoricalRejection);
const original=execFileSync('git',['diff','--name-only','f50cc999402b6ec7e6dbe8a0888fe5bf2062d2e1','--','src','tests','package.json','package-lock.json','scripts','docs/evidence/029-*','docs/evidence/028-*'],{encoding:'utf8'});
assert.equal(original,'');
const result={recordedAt:new Date().toISOString(),localLinks:links.length,links,recordedStateAndRejectionsMatch:true,originalEvidenceSourceTestsDependenciesUnchanged:true,sourceSha256:createHash('sha256').update(fs.readFileSync('docs/evidence/029-t04-manual.json')).digest('hex'),wordCounts:Object.fromEntries(files.map(f=>[f,fs.readFileSync(f,'utf8').trim().split(/\s+/).length]))};
fs.writeFileSync('/tmp/holdbook-judge-links.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result));
